// Turns the Error Trigger data into an email text and stores the report in Firebase.
const dbUrl = 'https://code-a-cuisine-7b803-default-rtdb.europe-west1.firebasedatabase.app';
const { execution = {}, workflow = {} } = $json;
const report = {
  at: new Date().toISOString(),
  workflow: workflow.name ?? 'unknown',
  workflowId: workflow.id ?? null,
  executionId: execution.id ?? null,
  executionUrl: execution.url ?? null,
  failedNode: execution.lastNodeExecuted ?? null,
  message: execution.error?.message ?? 'Unknown error',
  mode: execution.mode ?? null,
};

try {
  await this.helpers.httpRequest({
    method: 'POST',
    url: `${dbUrl}/logs/workflowErrors.json`,
    body: JSON.stringify(report),
    headers: { 'Content-Type': 'application/json' },
  });
} catch (error) {
  console.log(`Writing the error log failed: ${error.message}`);
}

const subject = `[Code à Cuisine] Error in workflow "${report.workflow}"`;
const text = [
  `Time: ${report.at}`,
  `Workflow: ${report.workflow}`,
  `Failed node: ${report.failedNode}`,
  `Error: ${report.message}`,
  `Execution: ${report.executionUrl ?? report.executionId}`,
].join('\n');

return [{ json: { ...report, subject, text } }];
